"""Record verified payload publication; push only final handoff metadata."""
import hashlib,json,os,subprocess
from pathlib import Path
H=Path(__file__).resolve().parent;R=H.parents[2];S=R/'.tmp'/H.name;entry=json.loads((H/'entry.json').read_text());publication=json.loads((H/'publication.json').read_text());payload=publication['remote_payload_commit'];ref='refs/heads/'+entry['target_branch'];env=dict(os.environ,GIT_INDEX_FILE=str(S/'full.index'),GIT_SSH_COMMAND='ssh -o BatchMode=yes -o ConnectTimeout=10 -o ServerAliveInterval=60 -o ServerAliveCountMax=10')
def git(*a,input=None):return subprocess.run(['git','-c','gc.auto=0',*a],cwd=R,env=env,input=input,stdout=subprocess.PIPE,stderr=subprocess.PIPE,check=True).stdout
assert git('ls-remote','origin',ref).decode().split()[0]==payload
changes=[n for n in git('diff','--name-only','-z').decode().split('\0')if n and not n.startswith(str(H.relative_to(R))+'/')];new=[n for n in git('ls-files','--others','--exclude-standard','-z').decode().split('\0')if n and not n.startswith(str(H.relative_to(R))+'/')];assert not changes and not new,{'late_modified':changes,'late_new':new}
assert git('rev-parse','HEAD').decode().strip()==entry['head'];assert hashlib.sha256((R/'.git/index').read_bytes()).hexdigest()==entry['index_sha256'];assert git('ls-remote','origin','refs/heads/main').decode().split()[0]==entry['origin_main']
v=json.loads((H/'verification.json').read_text());v['publication']='REMOTE PAYLOAD VERIFIED; final metadata commit follows';v['payload_commit']=payload;v['frozen_tree']=publication['frozen_tree'];v['published_payload_commits']=len(publication['pushed_commits']);v['published_changed_paths']=sum(x['paths']for x in publication['pushed_commits']);v['remote_main_unchanged']=True;v['shared_HEAD_index_preserved']=True;v['late_unpublished_worktree_paths']=[];v['manifest_note']='transfer-files.json describes initial captured payload; own handoff metadata added later is bounded by Git commit/tree';(H/'verification.json').write_text(json.dumps(v,ensure_ascii=False,indent=2))
report=(H/'REPORT.md').read_text()+f'''\n## Результат Git-transfer\n\nPayload опубликован и проверен через git ls-remote: `{payload}`, tree `{publication['frozen_tree']}`. Ветка `{entry['target_branch']}`;{len(publication['pushed_commits'])}payload commits,{v['published_changed_paths']}changed/added paths. Последний commit этой ветки дополнительно хранит этот итог, [publication.json](publication.json) и final verification; его SHA сообщается пользователю отдельно, чтобы не создавать self-reference.\n\nСекретных/запрещённых путей0, known-QA-secret matches0;76application Python AST и19JS syntax checks прошли. Full staged source manifest1017files; после capture новых source changes0.72безопасных ранее ignoredQAlogs включены явно; native PNG/JPG сохранены в Git image commits. Проверка секретов не является новым security audit приложения.\n\n`origin/main` остался `{entry['origin_main']}`. Исходный HEAD `{entry['head']}`, branch `{entry['branch']}` и sharedindex сохранены. WORKTREE намеренно остаётся dirty на исходном ПК; все зафиксированные изменения находятся в отдельной ветке переноса. Поздних неотправленных изменений вне этого собственного handoff не обнаружено на момент финальной сверки. Deploy и полный corpus не запускались.\n''';(H/'REPORT.md').write_text(report)
git('add','--',str(H.relative_to(R)));tree=git('write-tree').decode().strip();commit=git('-c','commit.gpgsign=false','commit-tree',tree,'-p',payload,input=b'Record verified module09 transfer and portable continuation prompt\n').decode().strip();(S/'final-commit.json').write_text(json.dumps({'commit':commit,'tree':tree,'payload':payload,'branch':entry['target_branch']},indent=2));print(json.dumps({'pushing_final_metadata':commit}),flush=True)
result=subprocess.run(['git','-c','gc.auto=0','push','origin',commit+':'+ref],cwd=R,env=env,capture_output=True,text=True);(S/'final-push.log').write_text(result.stdout+result.stderr);assert result.returncode==0,result.returncode
assert git('ls-remote','origin',ref).decode().split()[0]==commit;git('update-ref',ref,commit,payload);assert git('ls-remote','origin','refs/heads/main').decode().split()[0]==entry['origin_main'];assert hashlib.sha256((R/'.git/index').read_bytes()).hexdigest()==entry['index_sha256'];print(json.dumps({'VERIFIED_FINAL_SHA':commit,'branch':entry['target_branch'],'main_unchanged':True,'HEAD_index_preserved':True,'full_tests':'NOT RUN','deploy':'NOT RUN'}),flush=True)
